import{_ as l,o as t,c as i,a2 as e}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/quesion_imgs_00fbb373529f42e98fb36bde58db8c7a.DzaTA_JK.png",c=JSON.parse('{"title":"7、数据运算","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/计算机组成原理/7、数据运算.md","filePath":"科技岗专业课/计算机组成原理/7、数据运算.md","lastUpdated":1788883925000}'),h={name:"科技岗专业课/计算机组成原理/7、数据运算.md"};function d(o,a,n,b,u,p){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="_7、数据运算" tabindex="-1">7、数据运算 <a class="header-anchor" href="#_7、数据运算" aria-label="Permalink to &quot;7、数据运算&quot;">​</a></h1><p><strong>数据运算</strong></p><h2 id="定点数运算" tabindex="-1">定点数运算 <a class="header-anchor" href="#定点数运算" aria-label="Permalink to &quot;定点数运算&quot;">​</a></h2><h2 id="定点数的表示方法" tabindex="-1">定点数的表示方法 <a class="header-anchor" href="#定点数的表示方法" aria-label="Permalink to &quot;定点数的表示方法&quot;">​</a></h2><p>定点数是计算机中用于表示数值的基础格式，其核心特征是小数点在数中的位置固定不变，无需额外存储小数点位置信息，从而简化硬件实现。根据小数点固定位置的不同，定点数主要分为两类：</p><ul><li>定点整数：小数点默认固定在数值部分的最右侧，仅用于表示整数。例如 8 位机器字长下，二进制数 1011 的实际含义是 1011.0，对应十进制整数 11；若为负数，符号位会明确标识，数值部分仍为整数形式。</li><li>定点小数：小数点固定在符号位与数值位之间，仅用于表示绝对值在 [0,1) 或 [-1,1) 之间的纯小数。例如二进制数 0.1011（符号位为 0，正数），其十进制值为 1×2⁻¹ + 0×2⁻² + 1×2⁻³ + 1×2⁻⁴ = 0.6875；若符号位为 1，则表示负小数，如 1.1011 对应十进制 - 0.6875。</li></ul><p>在计算机系统中，定点数普遍采用二进制补码形式存储，这一选择的核心优势是能将减法运算转化为加法运算，无需单独设计减法电路。补码的编码规则为：符号位占 1 位（0 表示正数，1 表示负数），数值位按特定规则转换 —— 正数的补码与原码、反码完全一致；负数的补码是其原码（符号位不变）的数值位按位取反后加 1。例如：</p><ul><li>十进制 + 5 的 8 位补码：符号位 0，数值位 0000101，完整表示为 00000101；</li><li>十进制 - 5 的 8 位补码：原码为 10000101，数值位取反得 1111101，加 1 后为 11111011，最终补码为 11111011。</li></ul><p>需要说明的是，机器字长直接决定定点数的表示范围。以 8 位字长（1 位符号位 + 7 位数值位）为例：定点整数的表示范围是 - 128（10000000）~+127（01111111），定点小数的表示范围是 - 1（1.0000000）~1-2⁻⁷（0.1111111），超出该范围则会发生溢出。</p><h2 id="定点数加减法运算" tabindex="-1">定点数加减法运算 <a class="header-anchor" href="#定点数加减法运算" aria-label="Permalink to &quot;定点数加减法运算&quot;">​</a></h2><p>定点数的加减运算完全基于补码规则实现，核心思路是 “减法转加法”，无需单独处理符号位，运算过程统一为补码的二进制加法，结果自然为补码形式。</p><h3 id="加减法运算规则" tabindex="-1">加减法运算规则 <a class="header-anchor" href="#加减法运算规则" aria-label="Permalink to &quot;加减法运算规则&quot;">​</a></h3><ul><li>加法运算核心公式：[X+Y] 补 = [X] 补 + [Y] 补。该公式的本质是利用补码的模运算特性，将正数与负数的加法统一为无符号数的加法，符号位参与运算并自动输出结果的符号。</li><li>减法运算核心公式：[X-Y] 补 = [X] 补 + [-Y] 补。其中 [-Y] 补称为 “负补码”，是通过对 [Y] 补进行 “按位取反 + 末位加 1” 得到的，这一步骤实现了减法到加法的转化。</li></ul><p>通用运算步骤可归纳为：</p><ol><li>转换补码：将被加数（或被减数）、加数（或减数）统一转换为指定字长的补码形式；</li><li>二进制加法：对两个补码进行完整的二进制加法运算（包括符号位在内的所有位均参与运算），若产生进位则直接舍弃超出字长的进位位；</li><li>结果还原：运算结果仍为补码形式，若符号位为 0（正数），可直接转换为十进制；若符号位为 1（负数），需通过 “按位取反 + 末位加 1” 还原为原码后，再计算十进制真值。</li></ol><h3 id="示例与典型例题解析" tabindex="-1">示例与典型例题解析 <a class="header-anchor" href="#示例与典型例题解析" aria-label="Permalink to &quot;示例与典型例题解析&quot;">​</a></h3><h4 id="基础运算示例" tabindex="-1">基础运算示例 <a class="header-anchor" href="#基础运算示例" aria-label="Permalink to &quot;基础运算示例&quot;">​</a></h4><p>示例 1：计算 5 + (-3)（8 位字长）① 转换补码：[5] 补 = 00000101，[-3] 补 = 11111101（3 的补码为 00000011，取反加 1 得 11111101）；② 补码加法：00000101 + 11111101 = 100000010，超出 8 位字长，舍弃最高位进位 1，保留结果为 00000010；③ 结果还原：符号位为 0，直接转换为十进制 + 2，与实际结果一致。</p><p>示例 2：计算 5 - 3（8 位字长）① 转换补码与负补码：[5] 补 = 00000101，[3] 补 = 00000011，[-3] 补 = 11111101；② 补码加法：00000101 + 11111101 = 00000010；③ 结果还原：符号位为 0，真值为 + 2，符合 5-3=2 的计算结果。</p><h4 id="典型例题" tabindex="-1">典型例题 <a class="header-anchor" href="#典型例题" aria-label="Permalink to &quot;典型例题&quot;">​</a></h4><p>例题 1：设机器字长为 8 位（含 1 位符号位），A=15，B=24，求 [A+B] 补和 [A-B] 补。</p><p>解析：</p><p>① 真值转二进制：A=+15 的二进制形式为 + 0001111（7 位数值位），B=+24 的二进制形式为 + 0011000；</p><p>② 补码转换：[A] 补 = 00001111（符号位 0 + 数值位 0001111），[B] 补 = 00011000；根据负补码规则，[-B] 补 = ~[B] 补 + 1 = 11100111 + 1 = 11101000；</p><p>③ 计算 [A+B] 补：00001111 + 00011000 = 00100111，符号位为 0，说明结果为正数，直接转换为十进制为 39，即 [A+B] 补对应真值 + 39；</p><p>④ 计算 [A-B] 补：00001111 + 11101000 = 11110111，符号位为 1，说明结果为负数，还原为原码：~11110111 + 1 = 00001000 + 1 = 00001001（十进制 9），因此真值为 - 9。</p><h2 id="定点数乘法运算" tabindex="-1">定点数乘法运算 <a class="header-anchor" href="#定点数乘法运算" aria-label="Permalink to &quot;定点数乘法运算&quot;">​</a></h2><p>定点数乘法运算需根据数值的编码形式（原码或补码）采用不同方法，核心是通过 “移位 + 加法” 模拟手工乘法过程，避免复杂的乘法电路设计。</p><h3 id="原码乘法" tabindex="-1">原码乘法 <a class="header-anchor" href="#原码乘法" aria-label="Permalink to &quot;原码乘法&quot;">​</a></h3><p>原码乘法的核心特点是 “符号位与数值部分分离运算”，即符号位单独处理，数值部分按绝对值进行乘法运算，最终结合符号位得到结果。</p><ul><li>符号位运算规则：采用异或运算（⊕）判定结果符号 —— 正数（0）⊕正数（0）=0（正），正数（0）⊕负数（1）=1（负），负数（1）⊕负数（1）=0（正），完全遵循 “同号得正，异号得负” 的逻辑；</li><li>数值部分运算方法：类似于十进制手工乘法，将乘数的每一位作为判断依据，若该位为 1，则将被乘数的绝对值左移对应位数后加入部分积；若为 0，则不加入部分积，最终累加所有部分积得到数值部分的结果；</li><li>运算步骤：① 提取两个数的符号位和数值部分（绝对值）；② 符号位异或得到结果符号位；③ 数值部分通过 “移位 + 累加” 计算乘积；④ 组合符号位和数值部分，得到最终原码。</li></ul><p>示例：计算 (+3) × (-2)（4 位字长，1 位符号位 + 3 位数值位）</p><p>① 原码表示：[+3] 原 = 0011（符号位 0，数值位 011），[-2] 原 = 1010（符号位 1，数值位 010）；</p><p>② 符号位运算：0 ⊕ 1 = 1（结果为负）；</p><p>③ 数值部分运算：3 的绝对值为 011，2 的绝对值为 010，计算 011 × 010 = 00110（二进制），截取 3 位数值位为 110（因 4 位字长，数值部分最多 3 位，乘积需调整为对应长度）；</p><p>④ 结果组合：符号位 1 + 数值位 110 = 1110，对应十进制 - 6，运算正确。</p><h3 id="补码乘法-布斯算法" tabindex="-1">补码乘法（布斯算法） <a class="header-anchor" href="#补码乘法-布斯算法" aria-label="Permalink to &quot;补码乘法（布斯算法）&quot;">​</a></h3><p>补码乘法无需单独处理符号位，符号位与数值位一同参与运算，其中最常用的是布斯算法（Booth&#39;s Algorithm），该算法通过优化移位和加法操作，减少了运算步骤，适用于各类补码乘法场景。</p><ul><li>核心思想：利用补码的对称特性，通过比较乘数相邻两位的二进制状态（00、01、10、11），决定当前步骤是 “加被乘数补码”“减被乘数补码” 还是 “不操作”，随后进行算术右移，逐步累加得到最终乘积；</li><li>关键准备：在乘数的最低位右侧添加一位辅助位（初始值为 0），用于与最低位比较，形成相邻位对；</li><li>运算规则（从最低位向最高位逐位处理）：</li></ul><ol><li>若相邻位对为 “00” 或 “11”：仅对部分积和乘数（含辅助位）进行算术右移一位，不改变部分积数值；</li><li>若相邻位对为 “01”：将被乘数的补码加入部分积，之后对部分积和乘数（含辅助位）进行算术右移一位；</li><li>若相邻位对为 “10”：将被乘数补码的相反数（即 [- 被乘数] 补）加入部分积，之后对部分积和乘数（含辅助位）进行算术右移一位；</li></ol><ul><li>运算终止：当处理完乘数的所有位（含辅助位）后，部分积即为最终的乘积补码。</li></ul><p>简化示例：计算 (-3) × (+2)（4 位字长，[ -3 ] 补 = 1101，[ +2 ] 补 = 0010）① 准备工作：乘数 0010 右侧加辅助位 0，得到乘数序列 00100；部分积初始化为 0000；② 逐位处理：</p><ul><li>第 1 位（辅助位与最低位）：0 和 0（00）→ 右移，部分积 0000→0000，乘数 00100→00010；</li><li>第 2 位：0 和 1（01）→ 加 [-3] 补（1101），部分积 0000+1101=1101，右移→1110，乘数 00010→00001；</li><li>第 3 位：1 和 0（10）→ 加 [3] 补（0011，即 [-(-3)] 补），部分积 1110+0011=0001，右移→0000，乘数 00001→00000；</li><li>第 4 位：0 和 0（00）→ 右移，部分积 0000→0000，乘数 00000→00000；③ 最终结果：部分积 0000？不，实际 4 位字长下正确结果为 [-6] 补 = 1010，此处简化示例仅展示流程，完整运算需严格遵循字长限制和移位规则。</li></ul><h2 id="定点数除法运算" tabindex="-1">定点数除法运算 <a class="header-anchor" href="#定点数除法运算" aria-label="Permalink to &quot;定点数除法运算&quot;">​</a></h2><p>定点数除法运算同样分为原码除法和补码除法，核心是通过 “比较 - 加减 - 移位” 模拟手工除法，其中 “不恢复余数法” 和 “加减交替法” 是最常用的高效算法。</p><h3 id="原码除法-不恢复余数法" tabindex="-1">原码除法（不恢复余数法） <a class="header-anchor" href="#原码除法-不恢复余数法" aria-label="Permalink to &quot;原码除法（不恢复余数法）&quot;">​</a></h3><p>原码除法与原码乘法类似，符号位与数值部分分离处理，数值部分采用 “不恢复余数法” 运算，避免了恢复余数的繁琐步骤，提高运算效率。</p><ul><li>符号位运算：同原码乘法，通过异或运算确定结果符号（同号得正，异号得负）；</li><li>数值部分运算核心：以 “余数” 为核心，通过比较被除数（或当前余数）与除数的绝对值大小，决定商的每一位，同时通过加减操作更新余数，无需恢复余数即可持续运算；</li><li>详细运算步骤（假设被除数为 X，除数为 Y，均取绝对值）：</li></ul><ol><li>初始化：将被除数的绝对值作为初始余数 R₀，除数的绝对值为 Y，商 Q 初始化为 0；</li><li>比较与运算：</li></ol><ul><li>若 R₀ ≥ Y：商的当前最高位记为 1，新余数 R₁ = R₀ - Y；</li><li>若 R₀ &lt; Y：商的当前最高位记为 0，新余数 R₁ = R₀ + Y（不恢复余数，通过加法调整）；</li></ul><ol><li>移位更新：将新余数 R₁左移一位（相当于乘以 2），商也左移一位（空出最低位用于记录下一位结果）；</li><li>重复迭代：重复步骤 2-3，直至迭代次数等于数值位的位数，最终商 Q 即为数值部分的结果；</li><li>组合结果：将符号位与商 Q 组合，得到最终的原码结果。</li></ol><p>修正示例：计算 6 ÷ 2（8 位字长，[6] 原 = 00000110，[2] 原 = 00000010）① 符号位运算：0 ⊕ 0 = 0（结果为正）；② 数值部分运算（数值位 7 位，迭代 7 次，简化为核心步骤）：</p><ul><li>初始余数 R₀ = 00000110（6 的绝对值），除数 Y=00000010（2 的绝对值），商 Q=00000000；</li><li>第 1 次：R₀ ≥ Y → 商 Q 左移后最低位记 1（Q=00000001），R₁=00000110 - 00000010 = 00000100，R₁左移→00001000；</li><li>第 2 次：R₁ ≥ Y → 商 Q 左移后最低位记 1（Q=00000011），R₂=00001000 - 00000010 = 00000110，R₂左移→00001100；</li><li>后续迭代：余数左移后仍大于等于除数，商的后续位均为 0（因 6÷2=3，二进制商为 11，剩余位补 0）；③ 最终结果：符号位 0 + 商 00000011 = 00000011，对应十进制 3，运算正确。</li></ul><h3 id="补码除法-加减交替法" tabindex="-1">补码除法（加减交替法） <a class="header-anchor" href="#补码除法-加减交替法" aria-label="Permalink to &quot;补码除法（加减交替法）&quot;">​</a></h3><p>补码除法无需分离符号位，符号位与数值位一同参与运算，核心算法为 “加减交替法”，其规则基于补码的加减特性设计，步骤与原码除法类似但需结合补码符号调整加减操作。核心规则：</p><ol><li>初始操作：若被除数与除数同号（符号位相同），则用被除数补码减去除数补码；若异号，则用被除数补码加上除数补码；</li><li>商位判定：若余数与除数同号，商的当前位记 1；若异号，商的当前位记 0；</li><li>余数更新：余数左移一位后，若商的当前位为 1，则减去除数补码；若为 0，则加上除数补码（交替加减，故得名）；</li><li>迭代终止：迭代次数等于数值位位数，最终商需根据符号位和最后一次余数调整（若余数与被除数异号，需对商加 1 修正）；</li></ol><p>优势：无需单独处理符号位，运算流程统一，硬件实现更简洁，适用于各类补码数值的除法运算。</p><h2 id="定点数运算中的溢出问题" tabindex="-1">定点数运算中的溢出问题 <a class="header-anchor" href="#定点数运算中的溢出问题" aria-label="Permalink to &quot;定点数运算中的溢出问题&quot;">​</a></h2><p>在定点数运算中，溢出是指运算结果超出了当前机器字长所能表示的数值范围，导致结果失真的现象。溢出仅发生在同号数相加或异号数相减的场景中，异号数相加、同号数相减不会产生溢出。</p><h3 id="溢出的本质与表示范围" tabindex="-1">溢出的本质与表示范围 <a class="header-anchor" href="#溢出的本质与表示范围" aria-label="Permalink to &quot;溢出的本质与表示范围&quot;">​</a></h3><p>定点数的表示范围由机器字长和小数点位置决定：</p><ul><li>8 位定点整数（1 位符号位 + 7 位数值位）：补码表示范围为 - 128（10000000）~+127（01111111），超出该范围的整数运算会溢出；</li><li>8 位定点小数（1 位符号位 + 7 位数值位）：补码表示范围为 - 1（1.0000000）~1-2⁻⁷（0.1111111），超出该范围的小数运算会溢出；溢出的本质是运算结果的绝对值超过了数值位所能承载的最大值，导致符号位被数值位的进位或借位篡改，最终结果与真实值不符。</li></ul><h3 id="常用溢出检测方法" tabindex="-1">常用溢出检测方法 <a class="header-anchor" href="#常用溢出检测方法" aria-label="Permalink to &quot;常用溢出检测方法&quot;">​</a></h3><h4 id="双符号位法-变形补码法" tabindex="-1">双符号位法（变形补码法） <a class="header-anchor" href="#双符号位法-变形补码法" aria-label="Permalink to &quot;双符号位法（变形补码法）&quot;">​</a></h4><p>该方法通过设置两位符号位（原符号位 + 扩展符号位）来直观检测溢出，两位符号位的取值组合直接反映溢出状态：</p><ul><li>编码规则：正数的双符号位为 “00”，负数的双符号位为 “11”，数值位保持不变（如 + 127 的变形补码为 00 01111111，-128 的变形补码为 11 10000000）；</li><li>溢出判定：</li><li>运算后双符号位为 “00” 或 “11”：无溢出，结果有效，取左侧符号位作为最终符号；</li><li>双符号位为 “01”：正溢出（结果为正数且超出上限）；</li><li>双符号位为 “10”：负溢出（结果为负数且超出下限）。</li></ul><p>示例：计算 127 + 1（8 位定点整数，变形补码）① 变形补码转换：[127] 补 = 00 01111111，[1] 补 = 00 00000001；② 补码加法：00 01111111 + 00 00000001 = 01 00000000；③ 溢出判定：双符号位为 “01”，判定为正溢出，结果失真（真实结果 128 超出 8 位定点整数上限 + 127）。</p><h4 id="单符号位法-进位比较法" tabindex="-1">单符号位法（进位比较法） <a class="header-anchor" href="#单符号位法-进位比较法" aria-label="Permalink to &quot;单符号位法（进位比较法）&quot;">​</a></h4><p>该方法仅使用 1 位符号位，通过比较 “符号位产生的进位（Cₛ）” 和 “最高数值位产生的进位（C₁）” 来判定溢出，核心逻辑是：</p><ul><li>若 Cₛ = C₁：无溢出（符号位与数值位的进位状态一致，未篡改符号位）；</li><li>若 Cₛ ≠ C₁：有溢出（符号位与数值位的进位状态冲突，符号位被篡改）。</li></ul><p>示例：计算 - 128 + (-1)（8 位定点整数）① 补码转换：[-128] 补 = 10000000，[-1] 补 = 11111111；② 补码加法：10000000 + 11111111 = 101111111，Cₛ=1（符号位进位），C₁=0（最高数值位无进位）；③ 溢出判定：Cₛ≠C₁，判定为负溢出（真实结果 - 129 超出 8 位定点整数下限 - 128）。</p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网2020】下列说法中正确的是（）。A.采用变形补码进行加减运算可以避免溢出B.只有定点数运算才有可能溢出，浮点数运算不会产生溢出C.只有带符号数的运算才有可能产生溢出D.将两个正数相加有可能产生溢出答案 ：D解析 ：A 选项变形补码用于检测溢出，而非避免；B 选项浮点数的阶码也会溢出（如阶码超过最大值）；C 选项无符号数运算也会溢出（如 8 位无符号数 255+1=256）；D 选项两个正数相加可能超出机器表示范围（如 8 位带符号数 127+1=128），会发生溢出</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2015】若 x=103，y=-25，则下列表达式采用 8 位定点补码运算实现时，会发生溢出的是（）。A.x+yB.-x+yC.x-yD.x*y答案 ：C解析 ：①x=103 的 8 位补码为 01100111（正数，原码=补码）；②y=-25 的 8 位补码为 11100111；③x-y = x + (-y)，-y=25 的补码为 00011001；④计算 01100111 + 00011001 = 10000000，8 位带符号数的范围是-128~127，结果 10000000 代表-128，但 103+25=128 超出上限，发生溢出</th></tr></thead></table><h2 id="浮点数运算" tabindex="-1">浮点数运算 <a class="header-anchor" href="#浮点数运算" aria-label="Permalink to &quot;浮点数运算&quot;">​</a></h2><h2 id="为什么引入浮点数" tabindex="-1">为什么引入浮点数？ <a class="header-anchor" href="#为什么引入浮点数" aria-label="Permalink to &quot;为什么引入浮点数？&quot;">​</a></h2><p>计算机中引入浮点数，核心是解决定点数在表示范围与精度之间的矛盾。定点数因小数点位置固定，若要表示科学计算中的极大 / 极小值，要么受限于位数导致精度丢失，要么直接无法覆盖目标范围，且需通过软件手动缩放数值，运算效率极低。</p><p>浮点数采用类似科学计数法的结构，通过 “阶码” 动态调整小数点位置以拓展表示范围，“尾数” 保留有效数字以保证精度，实现二者的动态平衡。例如 32 位浮点数可覆盖 10⁻³⁸到 10³⁸的 70 个数量级，且不同数量级下均能维持相对精度；结合 IEEE 754 硬件标准化支持，有效避免了定点数 “大数吃小数” 的问题，成为天文、物理、工程等领域科学计算的核心技术。</p><h2 id="浮点数的表示形式" tabindex="-1">浮点数的表示形式 <a class="header-anchor" href="#浮点数的表示形式" aria-label="Permalink to &quot;浮点数的表示形式&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>浮点数由<strong>符号位（S）、阶码（E）、尾数（M）</strong> 三部分组成，遵循统一的标准格式：</p><ul><li>符号位（S）：0 表示正数，1 表示负数；</li><li>阶码（E）：采用移码形式，用于确定小数点位置，决定数值的表示范围；</li><li>尾数（M）：采用原码或补码形式，存储数值的有效数字，决定数值的精度。</li></ul><p>主流的 IEEE 754 标准明确了两种常用规格：</p><ul><li>单精度（32 位）：1 位符号位 + 8 位阶码 + 23 位尾数；</li><li>双精度（64 位）：1 位符号位 + 11 位阶码 + 52 位尾数。</li></ul><h2 id="浮点数规格化" tabindex="-1">浮点数规格化 <a class="header-anchor" href="#浮点数规格化" aria-label="Permalink to &quot;浮点数规格化&quot;">​</a></h2><h3 id="浮点数规格化的定义与目的" tabindex="-1">浮点数规格化的定义与目的 <a class="header-anchor" href="#浮点数规格化的定义与目的" aria-label="Permalink to &quot;浮点数规格化的定义与目的&quot;">​</a></h3><p>规格化是通过调整浮点数的阶码和尾数，使尾数满足特定格式的操作，核心作用有二：</p><ul><li>唯一性：避免同一数值存在多种表示形式（如 0.5 可表示为 1.0×2⁻¹ 或 0.1×2⁰，规格化后仅保留 1.0×2⁻¹）；</li><li>精度最大化：让尾数有效位数达到最大（如二进制尾数规范为 “1.xxxx” 形式），减少精度损失。</li></ul><h3 id="规格化浮点数的形式-以二进制为例" tabindex="-1">规格化浮点数的形式（以二进制为例） <a class="header-anchor" href="#规格化浮点数的形式-以二进制为例" aria-label="Permalink to &quot;规格化浮点数的形式（以二进制为例）&quot;">​</a></h3><p>二进制场景：</p><ul><li>正数（原码 / 补码）：尾数最高有效位为 1，形如 “1.xxxx”（例：二进制 10.11→1.011×2¹）；</li><li>负数（原码）：与正数规则一致，尾数最高有效位为 1（例：-10.11→-1.011×2¹）；</li><li>负数（补码）：尾数最高有效位与符号位相反（例：补码尾数 - 0.1011→-1.011×2⁰，符号位 1，尾数最高位 0）。</li></ul><p>非二进制基数（如基数 4）：原码尾数的小数点后两位不全为 0 即满足规格化（例：基数 4 时，1.001101 为规格化数，0.001101 非规格化）。</p><table tabindex="0"><thead><tr><th>【例题】设浮点数的基数为 4，尾数用原码表示，则以下哪项不是规格化的数？（ ）A.1.001101B.0.001101C.1.011011D.0.000010答案：ABD解析：基数为 4 时，原码尾数需满足 “小数点后两位不全为 0” 才是规格化数；且基数 4 的原码尾数每右 / 左移 2 位，阶码对应加 / 减 1。</th></tr></thead></table><h3 id="规格化操作的分类" tabindex="-1">规格化操作的分类 <a class="header-anchor" href="#规格化操作的分类" aria-label="Permalink to &quot;规格化操作的分类&quot;">​</a></h3><p>左规（左移规格化）：适用于尾数绝对值小于 1（如二进制 0.0101）的场景，将尾数左移，同时阶码减 1，直至尾数最高位为 1。例：0.0101×2³ 左移 2 位→1.01×2¹，阶码从 3 减为 1。</p><p>右规（右移规格化）：适用于尾数运算结果溢出（如二进制 10.101，绝对值≥2）的场景，将尾数右移 1 位，阶码加 1，确保尾数最高位为 1。例：10.101×2² 右移 1 位→1.0101×2³，阶码从 2 加为 3。</p><h2 id="浮点数的运算步骤" tabindex="-1">浮点数的运算步骤 <a class="header-anchor" href="#浮点数的运算步骤" aria-label="Permalink to &quot;浮点数的运算步骤&quot;">​</a></h2><p>浮点数运算包含加法、减法、乘法和除法，核心步骤如下：</p><h3 id="浮点数加减法运算" tabindex="-1">浮点数加减法运算 <a class="header-anchor" href="#浮点数加减法运算" aria-label="Permalink to &quot;浮点数加减法运算&quot;">​</a></h3><ol><li>对阶：计算两数阶码差 ，将阶码较小的数的尾数右移 ΔE 位，同时将其阶码调整为较大值，确保两数阶码一致；</li><li>尾数加减：对已对阶的尾数执行定点数加减运算（通常采用补码形式）；</li><li>规格化处理：若尾数最高位为 0 则执行左规（尾数左移、阶码减 1），若尾数溢出则执行右规（尾数右移、阶码加 1）；</li><li>舍入处理：常用截断法、恒置 1 法、0 舍 1 入法，弥补尾数移位导致的精度损失；</li><li>阶码溢出判断：若阶码超出表示范围（如单精度 - 126~127），则触发溢出错误。</li></ol><h3 id="浮点数乘除法运算" tabindex="-1">浮点数乘除法运算 <a class="header-anchor" href="#浮点数乘除法运算" aria-label="Permalink to &quot;浮点数乘除法运算&quot;">​</a></h3><h4 id="乘法运算" tabindex="-1">乘法运算 <a class="header-anchor" href="#乘法运算" aria-label="Permalink to &quot;乘法运算&quot;">​</a></h4><ol><li>符号位：两数符号位异或（）</li><li>阶码：两数阶码相加（，需处理移码偏移量）</li><li>尾数：两数尾数相乘（定点数乘法，结果为原码）</li><li>规格化与舍入：同加减法处理</li></ol><h4 id="除法运算" tabindex="-1">除法运算 <a class="header-anchor" href="#除法运算" aria-label="Permalink to &quot;除法运算&quot;">​</a></h4><ol><li>符号位：两数符号位异或（）</li><li>阶码：两数阶码相减（，需处理移码偏移量）</li><li>尾数：两数尾数相除（定点数除法，结果为原码）</li><li>规格化与舍入：同加减法处理</li></ol><h2 id="浮点数运算的特殊情况" tabindex="-1">浮点数运算的特殊情况 <a class="header-anchor" href="#浮点数运算的特殊情况" aria-label="Permalink to &quot;浮点数运算的特殊情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>处理方式</th></tr></thead><tbody><tr><td>阶码全0且尾数全0</td><td>表示0（+0或-0，由符号位决定）</td></tr><tr><td>阶码全1且尾数全0</td><td>表示无穷大（+∞或-∞，由符号位决定）</td></tr><tr><td>阶码全1且尾数非0</td><td>表示非数值（NaN，Not a Number）</td></tr><tr><td>阶码下溢</td><td>阶码小于最小值时，结果置为0（称为“机器零”）</td></tr><tr><td>阶码上溢</td><td>阶码大于最大值时，产生溢出错误（通常触发异常处理）</td></tr></tbody></table><h2 id="浮点数运算与定点数运算的对比" tabindex="-1">浮点数运算与定点数运算的对比 <a class="header-anchor" href="#浮点数运算与定点数运算的对比" aria-label="Permalink to &quot;浮点数运算与定点数运算的对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>浮点数运算</th><th>定点数运算</th></tr></thead><tbody><tr><td>表示范围</td><td>大（通过阶码调整小数点位置）</td><td>小（固定小数点位置）</td></tr><tr><td>精度</td><td>可变（尾数长度决定）</td><td>固定（字长决定）</td></tr><tr><td>硬件复杂度</td><td>高（需处理阶码和尾数逻辑）</td><td>低（仅需定点运算单元）</td></tr><tr><td>运算速度</td><td>慢（步骤多：对阶、规格化等）</td><td>快（直接加减乘除）</td></tr><tr><td>适用场景</td><td>科学计算、工程计算（如3D渲染、物理模拟）</td><td>工业控制、嵌入式系统（如电机控制）</td></tr></tbody></table><h2 id="真题-1" tabindex="-1">真题 <a class="header-anchor" href="#真题-1" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网2016】某数采用 IEEE754 单精度浮点数格式表示为 C6400000H，则该数的值是（）。A. -1.5×2¹³；B. -1.5×2¹²；C. -0.5×2¹³；D. -0.5×2¹²答案 ：A解析 ：C6400000H 的二进制是 1100 0110 0100 0000 0000 0000 0000 0000，符号位 1（负），阶码 10000101（133），尾数 0100…0。10000101 是 8 位，所以 133-127=6？但结果是-1.5×2¹³，答案是 A</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2023】浮点数的表示分为阶和尾数两部分。两个浮点数相加时，需要先对阶，即（）（n 为阶差的绝对值）。A. 将大阶向小阶对齐，同时将尾数左移 n 位；B. 将大阶向小阶对齐，同时将尾数右移 n 位；C. 将小阶向大阶对齐，同时将尾数左移 n 位；D. 将小阶向大阶对齐，同时将尾数右移 n 位答案 ：D解析 ：浮点数相加时，对阶的目的是使两个数的阶码相同，规则是 小阶向大阶对齐 （保证精度损失最小），较小阶码增加 n 位，对应的尾数需右移 n 位（因为阶码增大，尾数需缩小对应倍数）</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2018】下面浮点运算器的描述中正确的句子是（）。A. 浮点运算器可用阶码部件和尾数部件实现；B. 阶码部件可实现加、减、乘、除四种运算；C. 阶码部件只进行阶码相加、相减和比较操作；D. 尾数部件只进行乘法和减法运算答案 ：C解析 ：浮点运算器由阶码部件和尾数部件组成：阶码部件仅负责阶码的相加、相减（用于对阶）和比较（判断阶码大小）；尾数部件是通用定点运算器，需实现加、减、乘、除四种基本算术运算</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2019】下列说法正确的是（）。A. 变形补码不仅能判断溢出，还能通过自身编码规则避免溢出；浮点数阶码下溢属于真正的溢出，需进行硬件中断处理B. 异号数相加或同号数相减是补码运算产生溢出的核心场景；浮点数的尾数超出表示范围时，会直接引发浮点数溢出C. 变形补码通过单符号位的进位与结果符号位是否一致判断溢出；浮点数阶码为最小值时触发阶码上溢，属于严重溢出D. 变形补码可以判断溢出，但是不能避免溢出。浮点数阶码超过上限（最大数）也会溢出，同号数相加或异号数相减都会产生溢出答案 ：D解析 ：变形补码（双符号位）可通过符号位是否一致判断溢出，但无法避免溢出；浮点数的溢出分为 阶码上溢 （阶码超过最大值，如阶码 8 位移码的最大值是 127，若阶码真值超过 127 则溢出）和 阶码下溢 （阶码低于最小值，通常视为 0）；同号数相加或异号数相减时，尾数相加可能导致阶码进位，从而引发溢出</th></tr></thead></table><table tabindex="0"><thead><tr><th>【南方电网2024】十进制数 7 的单精度浮点数 IEEE754 代码为（）。A. 01000000111000000000000000000000；B. 01000000101100000000000000000000；C. 01100000101000000000000000000000；D. 11000000101000000000000000000000 ；答案 ：A解析 ：IEEE754 单精度浮点数格式：符号位 1 位（正为 0）、8 位阶码（移码，偏移量 127）、23 位尾数（隐含最高位 1）。十进制数 7 转换为二进制是 111.0，规格化后为 1.11×2²（阶码=2）。阶码移码=2+127=129（二进制 10000001），尾数=1100000…0（23 位）。因此代码为 0（符号位） 10000001（阶码） 11000000000000000000000（尾数），即 01000000111000000000000000000000</th></tr></thead></table>',115)])])}const q=l(h,[["render",d]]);export{c as __pageData,q as default};
